package com.shiphappens.logistics.entity;
import jakarta.persistence.*;
@Entity @Table(name="warehouses") public class Warehouse { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="warehouse_code") private String warehouseCode; private String name,address,city,state,status; private int capacity; @Column(name="current_load") private int currentLoad; public Long getId(){return id;} public String getWarehouseCode(){return warehouseCode;} public void setWarehouseCode(String v){warehouseCode=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getCity(){return city;} public void setCity(String v){city=v;} public String getState(){return state;} public void setState(String v){state=v;} public int getCapacity(){return capacity;} public void setCapacity(int v){capacity=v;} public int getCurrentLoad(){return currentLoad;} public void setCurrentLoad(int v){currentLoad=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }
